      state%op3%c3 => state%s11
      tmp1 = state%cx_s2**(2)
      state%cx_s15 = 0.5_wp*tmp1
      state%cx_s16 = state%cx_s15*state%cx_s14
      state%cx_s17 = state%cx_s12*state%cx_s16
      do i = 1, npt
         tmp2 = 1.0_wp/state%a(i)
