         tmp15 = -tmp14
         state%cx_s23(i) = tmp15
      end do
      tmp16 = 0.0_wp
      tmp17 = 0.0_wp
      tmp18 = 0.0_wp
      tmp19 = 0.0_wp
      tmp20 = 0.0_wp
      tmp21 = 0.0_wp
      block
         real(wp) :: tmp28, tmp29, tmp30, tmp31, tmp32, tmp33, tmp36, tmp39, tmp43, tmp37, tmp38, &
