            do i = 1, j - 1
               tmp37 = state%s6(i) + tmp36
               tmp38 = tmp28*tmp37
               tmp40 = state%s7(i) + tmp39
               tmp41 = tmp40*tmp31
               tmp42 = tmp38 + tmp41
               tmp44 = state%s9(i) + tmp43
               tmp45 = tmp44*tmp33
               tmp46 = tmp42 + tmp45
               tmp47 = tmp46*tmp37
               tmp48 = tmp37**(2)
               tmp49 = tmp40**(2)
               tmp50 = tmp48 + tmp49
               tmp51 = tmp44**(2)
               tmp52 = tmp50 + tmp51
               tmp53 = 1.0_wp/sqrt(tmp52)
               tmp54 = tmp53**(5)
               tmp55 = tmp47*tmp54
               tmp56 = (-3.0_wp)*tmp55
               tmp57 = tmp53**(3)
               tmp58 = tmp28*tmp57
               tmp59 = tmp56 + tmp58
               tmp60 = tmp59*tmp34
               tmp61 = tmp60*state%cx_s12(i)
               tmp16_p(i) = tmp16_p(i) + tmp61
               tmp62 = -tmp61
               tmp22 = tmp22 + tmp62
               tmp63 = tmp40*tmp46
               tmp64 = tmp63*tmp54
               tmp65 = (-3.0_wp)*tmp64
               tmp66 = tmp31*tmp57
               tmp67 = tmp65 + tmp66
               tmp68 = tmp67*tmp34
               tmp69 = tmp68*state%cx_s12(i)
               tmp17_p(i) = tmp17_p(i) + tmp69
               tmp70 = -tmp69
               tmp23 = tmp23 + tmp70
               tmp71 = tmp44*tmp46
               tmp72 = tmp71*tmp54
               tmp73 = (-3.0_wp)*tmp72
               tmp74 = tmp33*tmp57
