               tmp24 = tmp24 + tmp78
               tmp79 = tmp34*tmp57
               tmp80 = tmp79*tmp37
               tmp81 = tmp80*state%cx_s12(i)
               tmp25 = tmp25 + tmp81
               tmp82 = tmp40*tmp34
               tmp83 = tmp82*tmp57
               tmp84 = tmp83*state%cx_s12(i)
               tmp26 = tmp26 + tmp84
               tmp85 = tmp44*tmp34
               tmp86 = tmp85*tmp57
               tmp87 = tmp86*state%cx_s12(i)
