               tmp61 = tmp60*state%cx_s12(i)
               tmp16_p(i) = tmp16_p(i) + tmp61
               tmp62 = -tmp61
               tmp22 = tmp22 + tmp62
               tmp63 = tmp40*tmp46
               tmp64 = tmp63*tmp54
               tmp65 = (-3.0_wp)*tmp64
               tmp66 = tmp31*tmp57
               tmp67 = tmp65 + tmp66
               tmp68 = tmp67*tmp34
               tmp69 = tmp68*state%cx_s12(i)
               tmp17_p(i) = tmp17_p(i) + tmp69
               tmp70 = -tmp69
               tmp23 = tmp23 + tmp70
               tmp71 = tmp44*tmp46
               tmp72 = tmp71*tmp54
               tmp73 = (-3.0_wp)*tmp72
               tmp74 = tmp33*tmp57
               tmp75 = tmp73 + tmp74
               tmp76 = tmp34*tmp75
               tmp77 = tmp76*state%cx_s12(i)
               tmp18_p(i) = tmp18_p(i) + tmp77
               tmp78 = -tmp77
               tmp24 = tmp24 + tmp78
               tmp79 = tmp34*tmp57
               tmp80 = tmp79*tmp37
               tmp81 = tmp80*state%cx_s12(i)
               tmp25 = tmp25 + tmp81
               tmp82 = tmp40*tmp34
               tmp83 = tmp82*tmp57
               tmp84 = tmp83*state%cx_s12(i)
               tmp26 = tmp26 + tmp84
               tmp85 = tmp44*tmp34
               tmp86 = tmp85*tmp57
