         call fatal_error(error, "[dpcm_original_point_complex_tangent] hvp_vn: wrong shape")
         return
      end if
      do blk = 1, nblk
         call dpcm_original_point_complex_tangent_one(state, dr(:, :, blk), dn(:, :, blk), &
                                                      dk1(:, blk), dk2(:, blk), da(:, blk), &
                                                      dv(:, blk), dvn(:, blk), hvp_r(:, :, blk), &
                                                      hvp_n(:, :, blk), hvp_k1(:, blk), &
                                                      hvp_k2(:, blk), hvp_a(:, blk), &
                                                      hvp_v(:, blk), hvp_vn(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine dpcm_original_point_complex_tangent

