               tmp49 = tmp40**(2)
               tmp50 = tmp48 + tmp49
               tmp51 = tmp44**(2)
               tmp52 = tmp50 + tmp51
               tmp53 = 1.0_wp/sqrt(tmp52)
               tmp54 = tmp53**(5)
               tmp55 = tmp47*tmp54
