               tmp62 = -tmp61
               tmp22 = tmp22 + tmp62
               tmp63 = tmp40*tmp46
               tmp64 = tmp63*tmp54
               tmp65 = (-3.0_wp)*tmp64
               tmp66 = tmp31*tmp57
               tmp67 = tmp65 + tmp66
               tmp68 = tmp67*tmp34
               tmp69 = tmp68*state%s12(i)
               tmp17_p(i) = tmp17_p(i) + tmp69
