               tmp76 = tmp34*tmp75
               tmp77 = tmp76*state%s12(i)
               tmp18_p(i) = tmp18_p(i) + tmp77
               tmp78 = -tmp77
               tmp24 = tmp24 + tmp78
               tmp79 = tmp34*tmp57
