   !> DPCM, original form (point charges): linear response of the v, vn gradient
   !>
   !> - Directions of v, vn only; the state is not changed
   !> - Needs dpcm_original_point_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_mf_response(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_state), intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Direction for vn
      real(wp), contiguous, intent(in) :: dvn(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Hessian times direction, vn block
      real(wp), contiguous, intent(out) :: hvp_vn(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%ready < 3) then
         call fatal_error(error, &
                          "[dpcm_original_point_mf_response] call dpcm_original_point_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_mf_response] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_mf_response] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_mf_response] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_mf_response] hvp_vn: wrong shape")
         return
      end if
      do blk = 1, nblk
         call dpcm_original_point_mf_response_one(state, dv(:, blk), dvn(:, blk), hvp_v(:, blk), &
                                                  hvp_vn(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine dpcm_original_point_mf_response

   !> One direction of dpcm_original_point_mf_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_mf_response_one(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_state), target, intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:)
      !> Direction for vn
      real(wp), contiguous, intent(in) :: dvn(:)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:)
      !> Hessian times direction, vn block
      real(wp), contiguous, intent(out) :: hvp_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_mf_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_mf_response_one] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_mf_response_one] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_mf_response_one] hvp_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_mf_response_one] allocation failed")
         return
      end if

      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%n => state%n
      state%op2%k1 => state%k1
      state%op2%k2 => state%k2
      state%op2%a => state%a
      state%op2%c1 => state%s3
      tmp1 = 0.0_wp
      call state%solver%solve(state%op2, .false., dvn, tmp1, error)
      if (allocated(error)) return
      hvp_v = state%s13*tmp1
      tmp2 = 0.0_wp
      call state%solver%solve(state%op2, .true., dv, tmp2, error)
      if (allocated(error)) return
      hvp_vn = state%s13*tmp2
   end subroutine dpcm_original_point_mf_response_one

   !> DPCM, original form (point charges): energy derivatives with respect to the solvent parameters
   !>
   !> - For the inputs of the last solve; independent of weights, which does not compute them
   !> - Needs dpcm_original_point_solve on the same state first
   !> - Keeps the state as it is; may be repeated in any order
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[out] grad_eps  partial derivative of the energy with respect to eps
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_mf_param_weights(state, grad_eps, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to eps
      real(wp), intent(out) :: grad_eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp4(:), tmp5(:), tmp6(:), tmp13(:)
      real(wp) :: tmp2, tmp3, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, tmp42, tmp43, tmp44, tmp45, &
                  tmp46
      integer :: i, j

      stat = 0
      npt = state%npt
      if (state%ready < 3) then
         call fatal_error(error, &
                          "[dpcm_original_point_mf_param_weights] call dpcm_original_point_solve first")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp13(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_mf_param_weights] allocation failed")
         return
      end if

      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%n => state%n
      state%op2%k1 => state%k1
      state%op2%k2 => state%k2
      state%op2%a => state%a
      state%op2%c1 => state%s3
      tmp1 = 0.5_wp*state%v
      tmp2 = dot(tmp1, state%s12)
      tmp3 = (-0.5_wp)*state%s2
      tmp4 = tmp3*state%s14
      do i = 1, npt
         tmp7 = state%k1(i) + state%k2(i)
         tmp8 = 1.0_wp/state%a(i)
         tmp9 = 12.566370614359172_wp*tmp8
         tmp10 = sqrt(tmp9)
         tmp11 = tmp7*tmp10
         tmp12 = (-0.26735_wp)*tmp11
         tmp6(i) = tmp12
      end do
      tmp13 = tmp6*state%s12
      tmp5 = tmp13
      block
         real(wp) :: tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, tmp21, tmp22, tmp25, tmp29, tmp14, &
                     tmp23, tmp24, tmp26, tmp27, tmp28, tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, &
                     tmp36, tmp37, tmp38, tmp39, tmp40, tmp41

         !$omp parallel &
         !$omp& private(i, j) &
         !$omp& shared(npt, state, tmp5) &
         !$omp& default(private)
         !$omp do schedule(static)
         do j = 1, npt
            tmp15 = state%s5(j)
            tmp16 = state%s6(j)
            tmp17 = state%s7(j)
            tmp18 = state%s8(j)
            tmp19 = state%s9(j)
            tmp20 = state%s10(j)
            tmp21 = state%s12(j)
            tmp22 = -tmp16
            tmp25 = -tmp17
            tmp29 = -tmp19
            tmp14 = 0.0_wp
            !$omp simd &
            !$omp& private(tmp23, tmp24, tmp26, tmp27, tmp28, tmp30, tmp31, tmp32) &
            !$omp& private(tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, tmp39, tmp40) &
            !$omp& private(tmp41) &
            !$omp& reduction(+: tmp14)
            do i = 1, j - 1
               tmp23 = state%s6(i) + tmp22
               tmp24 = tmp15*tmp23
               tmp26 = state%s7(i) + tmp25
               tmp27 = tmp26*tmp18
               tmp28 = tmp24 + tmp27
               tmp30 = state%s9(i) + tmp29
               tmp31 = tmp30*tmp20
               tmp32 = tmp28 + tmp31
               tmp33 = tmp23**(2)
               tmp34 = tmp26**(2)
               tmp35 = tmp33 + tmp34
               tmp36 = tmp30**(2)
               tmp37 = tmp35 + tmp36
               tmp38 = 1.0_wp/sqrt(tmp37)
               tmp39 = tmp38**(3)
               tmp40 = tmp32*tmp39
               tmp41 = tmp40*state%s12(i)
               tmp14 = tmp14 + tmp41
            end do
            !$omp simd &
            !$omp& private(tmp23, tmp24, tmp26, tmp27, tmp28, tmp30, tmp31, tmp32) &
            !$omp& private(tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, tmp39, tmp40) &
            !$omp& private(tmp41) &
            !$omp& reduction(+: tmp14)
            do i = j + 1, npt
               tmp23 = state%s6(i) + tmp22
               tmp24 = tmp15*tmp23
               tmp26 = state%s7(i) + tmp25
               tmp27 = tmp26*tmp18
               tmp28 = tmp24 + tmp27
               tmp30 = state%s9(i) + tmp29
               tmp31 = tmp30*tmp20
               tmp32 = tmp28 + tmp31
               tmp33 = tmp23**(2)
               tmp34 = tmp26**(2)
               tmp35 = tmp33 + tmp34
               tmp36 = tmp30**(2)
               tmp37 = tmp35 + tmp36
               tmp38 = 1.0_wp/sqrt(tmp37)
               tmp39 = tmp38**(3)
               tmp40 = tmp32*tmp39
               tmp41 = tmp40*state%s12(i)
               tmp14 = tmp14 + tmp41
            end do
            tmp5(j) = tmp5(j) + tmp14
         end do
         !$omp end do
         !$omp end parallel
      end block
      tmp42 = dot(tmp4, tmp5)
      tmp43 = -tmp42
      tmp44 = tmp2 + tmp43
      tmp45 = state%s1**(-2)
      tmp46 = tmp44*tmp45
      grad_eps = 2.0_wp*tmp46
   end subroutine dpcm_original_point_mf_param_weights

   !> DPCM, original form (point charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs dpcm_original_point_assemble on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_complex_mf_medium(state, eps, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_complex_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      complex(wp), intent(in) :: eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp) :: tmp1, tmp2

      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, &
                          "[dpcm_original_point_complex_mf_medium] call dpcm_original_point_assemble first")
         return
      end if
      state%cx_ready = 0
      if (allocated(state%cx_v)) deallocate (state%cx_v)
      if (allocated(state%cx_s12)) deallocate (state%cx_s12)
      if (allocated(state%cx_s14)) deallocate (state%cx_s14)
      if (allocated(state%cx_s16)) deallocate (state%cx_s16)
      if (allocated(state%cx_s17)) deallocate (state%cx_s17)
      if (allocated(state%cx_s18)) deallocate (state%cx_s18)
      if (allocated(state%cx_s19)) deallocate (state%cx_s19)
      if (allocated(state%cx_s21)) deallocate (state%cx_s21)
      if (allocated(state%cx_s22)) deallocate (state%cx_s22)
      if (allocated(state%cx_s23)) deallocate (state%cx_s23)
      if (stat == 0) allocate (state%cx_v(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s12(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s14(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s16(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s17(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s18(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s19(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s21(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s22(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s23(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_medium] allocation failed")
         return
      end if
      state%cx_s12 = 0.0_wp
      state%cx_s14 = 0.0_wp
      state%cx_ready = 1
      state%cx_assembled = state%assembled
      ! Inputs that do not enter these outputs
      associate (unused1 => eps)
      end associate

      state%op4%npt = npt
      state%op4%npoint = npt
      state%op4%id = 4
      state%op4%points => state%r
      state%op4%r => state%r
      state%op4%n => state%n
      state%op4%k1 => state%k1
      state%op4%k2 => state%k2
      state%op4%a => state%a
      state%op4%c1 => state%s3
      state%cx_s1 = eps + 1.0_wp
      tmp1 = 1.0_wp/state%cx_s1
      tmp2 = (-2.0_wp)*tmp1
      state%cx_s2 = 1.0_wp + tmp2
      state%cx_s4 = -state%cx_s2
      state%op4%c2 = state%cx_s4
      call state%solver%setup_complex(state%op4, error)
      if (allocated(error)) return
      state%cx_s13 = 0.5_wp*state%cx_s2

      state%cx_ready = 2
   end subroutine dpcm_original_point_complex_mf_medium

   !> DPCM, original form (point charges): energy, solution and gradient for v, vn
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs dpcm_original_point_complex_medium on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[in] vn  outward normal derivative of the solute potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] grad_vn  partial derivative of the energy with respect to vn
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_complex_mf_solve(state, v, vn, energy, q, grad_v, grad_vn, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_complex_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      complex(wp), contiguous, intent(in) :: v(:)
      !> Outward normal derivative of the solute potential at the surface points
      complex(wp), contiguous, intent(in) :: vn(:)
      !> Solvation energy
      complex(wp), intent(out) :: energy
      !> Apparent surface charges
      complex(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      complex(wp), contiguous, intent(out) :: grad_v(:)
      !> Partial derivative of the energy with respect to vn
      complex(wp), contiguous, intent(out) :: grad_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp5(:)
      real(wp) :: tmp6, tmp7, tmp8, tmp9, tmp10, tmp11
      complex(wp), allocatable :: tmp2(:), tmp3(:), tmp4(:), tmp12(:), tmp41(:), tmp42(:), &
                                  tmp43(:), tmp44(:)
      complex(wp) :: tmp1, tmp45
      integer :: i, j

      stat = 0
      npt = state%npt
      if (state%cx_ready < 2 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[dpcm_original_point_complex_mf_solve] call dpcm_original_point_complex_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_solve] v: wrong shape")
         return
      end if
      if (any(shape(vn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_solve] vn: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_solve] grad_v: wrong shape")
         return
      end if
      if (any(shape(grad_vn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_solve] grad_vn: wrong shape")
         return
      end if
      allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat == 0) allocate (tmp41(npt), stat=stat)
      if (stat == 0) allocate (tmp42(npt), stat=stat)
      if (stat == 0) allocate (tmp43(npt), stat=stat)
      if (stat == 0) allocate (tmp44(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_solve] allocation failed")
         return
      end if
      state%cx_ready = 2

      state%op4%points => state%r
      state%op4%r => state%r
      state%op4%n => state%n
      state%op4%k1 => state%k1
      state%op4%k2 => state%k2
      state%op4%a => state%a
      state%op4%c1 => state%s3
      state%cx_v = v
      call state%solver%solve_complex(state%op4, .false., vn, state%cx_s12, error)
      if (allocated(error)) return
      call state%solver%solve_complex(state%op4, .true., state%cx_v, state%cx_s14, error)
      if (allocated(error)) return
      q = state%cx_s2*state%cx_s12
      tmp1 = sum(state%cx_v*q)
      energy = 0.5_wp*tmp1
      grad_v = state%cx_s13*state%cx_s12
      grad_vn = state%cx_s13*state%cx_s14
      if (state%solver%inexact()) then
         ! First-order correction for the residuals of the solves
         tmp2 = state%s3*state%cx_s12
         tmp3 = 6.283185307179586_wp*tmp2
         do i = 1, npt
            tmp6 = state%k1(i) + state%k2(i)
            tmp7 = 1.0_wp/state%a(i)
            tmp8 = 12.566370614359172_wp*tmp7
            tmp9 = sqrt(tmp8)
            tmp10 = tmp6*tmp9
            tmp11 = (-0.26735_wp)*tmp10
            tmp5(i) = tmp11
         end do
         tmp12 = tmp5*state%cx_s12
         tmp4 = tmp12
         block
            real(wp) :: tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp21, tmp24, tmp28, tmp22, &
                        tmp23, tmp25, tmp26, tmp27, tmp29, tmp30, tmp31, tmp32, tmp33, tmp34, &
                        tmp35, tmp36, tmp37, tmp38, tmp39
            complex(wp) :: tmp20, tmp13, tmp40

            !$omp parallel &
            !$omp& private(i, j) &
            !$omp& shared(npt, state, tmp4) &
            !$omp& default(private)
            !$omp do schedule(static)
            do j = 1, npt
               tmp14 = state%s5(j)
               tmp15 = state%s6(j)
               tmp16 = state%s7(j)
               tmp17 = state%s8(j)
               tmp18 = state%s9(j)
               tmp19 = state%s10(j)
               tmp20 = state%cx_s12(j)
               tmp21 = -tmp15
               tmp24 = -tmp16
               tmp28 = -tmp18
               tmp13 = 0.0_wp
               !$omp simd &
               !$omp& private(tmp22, tmp23, tmp25, tmp26, tmp27, tmp29, tmp30, tmp31) &
               !$omp& private(tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, tmp39) &
               !$omp& private(tmp40) &
               !$omp& reduction(+: tmp13)
               do i = 1, j - 1
                  tmp22 = state%s6(i) + tmp21
                  tmp23 = tmp14*tmp22
                  tmp25 = state%s7(i) + tmp24
                  tmp26 = tmp25*tmp17
                  tmp27 = tmp23 + tmp26
                  tmp29 = state%s9(i) + tmp28
                  tmp30 = tmp29*tmp19
                  tmp31 = tmp27 + tmp30
                  tmp32 = tmp22**(2)
                  tmp33 = tmp25**(2)
                  tmp34 = tmp32 + tmp33
                  tmp35 = tmp29**(2)
                  tmp36 = tmp34 + tmp35
                  tmp37 = 1.0_wp/sqrt(tmp36)
                  tmp38 = tmp37**(3)
                  tmp39 = tmp31*tmp38
                  tmp40 = tmp39*state%cx_s12(i)
                  tmp13 = tmp13 + tmp40
               end do
               !$omp simd &
               !$omp& private(tmp22, tmp23, tmp25, tmp26, tmp27, tmp29, tmp30, tmp31) &
               !$omp& private(tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, tmp39) &
               !$omp& private(tmp40) &
               !$omp& reduction(+: tmp13)
               do i = j + 1, npt
                  tmp22 = state%s6(i) + tmp21
                  tmp23 = tmp14*tmp22
                  tmp25 = state%s7(i) + tmp24
                  tmp26 = tmp25*tmp17
                  tmp27 = tmp23 + tmp26
                  tmp29 = state%s9(i) + tmp28
                  tmp30 = tmp29*tmp19
                  tmp31 = tmp27 + tmp30
                  tmp32 = tmp22**(2)
                  tmp33 = tmp25**(2)
                  tmp34 = tmp32 + tmp33
                  tmp35 = tmp29**(2)
                  tmp36 = tmp34 + tmp35
                  tmp37 = 1.0_wp/sqrt(tmp36)
                  tmp38 = tmp37**(3)
                  tmp39 = tmp31*tmp38
                  tmp40 = tmp39*state%cx_s12(i)
                  tmp13 = tmp13 + tmp40
               end do
               tmp4(j) = tmp4(j) + tmp13
            end do
            !$omp end do
            !$omp end parallel
         end block
         tmp41 = state%cx_s4*tmp4
         tmp42 = tmp3 + tmp41
         tmp43 = -tmp42
         tmp44 = vn + tmp43
         tmp45 = sum(grad_vn*tmp44)
         energy = energy + tmp45
      end if

      state%cx_ready = 3
   end subroutine dpcm_original_point_complex_mf_solve

   !> DPCM, original form (point charges): energy gradient with respect to the cavity inputs
   !>
   !> - For the inputs of the last solve
   !> - Needs dpcm_original_point_complex_solve on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[out] grad_r  partial derivative of the energy with respect to r
   !> @param[out] grad_n  partial derivative of the energy with respect to n
   !> @param[out] grad_k1  partial derivative of the energy with respect to k1
   !> @param[out] grad_k2  partial derivative of the energy with respect to k2
   !> @param[out] grad_a  partial derivative of the energy with respect to a
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_complex_mf_weights(state, grad_r, grad_n, grad_k1, grad_k2, &
                                                     grad_a, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_complex_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to r
      complex(wp), contiguous, intent(out) :: grad_r(:, :)
      !> Partial derivative of the energy with respect to n
      complex(wp), contiguous, intent(out) :: grad_n(:, :)
      !> Partial derivative of the energy with respect to k1
      complex(wp), contiguous, intent(out) :: grad_k1(:)
      !> Partial derivative of the energy with respect to k2
      complex(wp), contiguous, intent(out) :: grad_k2(:)
      !> Partial derivative of the energy with respect to a
      complex(wp), contiguous, intent(out) :: grad_a(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, tmp13, &
                  tmp14, tmp15
      complex(wp), allocatable :: tmp16(:), tmp17(:), tmp18(:), tmp19(:), tmp20(:), tmp21(:), &
                                  tmp88(:), tmp89(:)
      complex(wp) :: tmp1
      complex(wp), allocatable :: tmp16_p(:), tmp17_p(:), tmp18_p(:)
      integer :: i, j

      stat = 0
      npt = state%npt
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[dpcm_original_point_complex_mf_weights] call dpcm_original_point_complex_solve first")
         return
      end if
      if (any(shape(grad_r) /= [3, npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_weights] grad_r: wrong shape")
         return
      end if
      if (any(shape(grad_n) /= [3, npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_weights] grad_n: wrong shape")
         return
      end if
      if (any(shape(grad_k1) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_weights] grad_k1: wrong shape")
         return
      end if
      if (any(shape(grad_k2) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_weights] grad_k2: wrong shape")
         return
      end if
      if (any(shape(grad_a) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_weights] grad_a: wrong shape")
         return
      end if
      allocate (tmp16(npt), stat=stat)
      if (stat == 0) allocate (tmp17(npt), stat=stat)
      if (stat == 0) allocate (tmp18(npt), stat=stat)
      if (stat == 0) allocate (tmp19(npt), stat=stat)
      if (stat == 0) allocate (tmp20(npt), stat=stat)
      if (stat == 0) allocate (tmp21(npt), stat=stat)
      if (stat == 0) allocate (tmp88(npt), stat=stat)
      if (stat == 0) allocate (tmp89(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_weights] allocation failed")
         return
      end if
      state%cx_ready = 3

      state%op4%points => state%r
      state%op4%r => state%r
      state%op4%n => state%n
      state%op4%k1 => state%k1
      state%op4%k2 => state%k2
      state%op4%a => state%a
      state%op4%c1 => state%s3
      tmp1 = state%cx_s2**(2)
      state%cx_s15 = 0.5_wp*tmp1
      state%cx_s16 = state%cx_s15*state%cx_s14
      state%cx_s17 = state%cx_s12*state%cx_s16
      do i = 1, npt
         tmp2 = 1.0_wp/state%a(i)
         tmp3 = 12.566370614359172_wp*tmp2
         tmp4 = sqrt(tmp3)
         tmp5 = (-0.26735_wp)*tmp4
         state%cx_s18(i) = tmp5
      end do
      do i = 1, npt
         tmp6 = 1.0_wp/state%a(i)
         tmp7 = 12.566370614359172_wp*tmp6
         tmp8 = 1.0_wp/sqrt(tmp7)
         tmp9 = state%k1(i) + state%k2(i)
         tmp10 = tmp8*tmp9
         tmp11 = state%a(i)**(-2)
         tmp12 = tmp10*tmp11
         tmp13 = 1.6798095918744622_wp*tmp12
         state%cx_s19(i) = tmp13
      end do
      state%cx_s20 = (-3.141592653589793_wp)*state%cx_s2
      state%cx_s21 = state%cx_s20*state%cx_s14
