         return
      end if
      if (any(shape(hvp_k1) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_tangent] hvp_k1: wrong shape")
         return
      end if
      if (any(shape(hvp_k2) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_tangent] hvp_k2: wrong shape")
