   !> DPCM, original form (point charges): linear response of the v, vn gradient
   !>
   !> - Directions of v, vn only; the state is not changed
   !> - Needs dpcm_original_point_complex_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_complex_mf_response(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_complex_state), intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:, :)
      !> Direction for vn
      complex(wp), contiguous, intent(in) :: dvn(:, :)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Hessian times direction, vn block
      complex(wp), contiguous, intent(out) :: hvp_vn(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[dpcm_original_point_complex_mf_response] call dpcm_original_point_complex_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_response] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_response] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_response] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_response] hvp_vn: wrong shape")
         return
      end if
      do blk = 1, nblk
         call dpcm_original_point_complex_mf_response_one(state, dv(:, blk), dvn(:, blk), &
                                                          hvp_v(:, blk), hvp_vn(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine dpcm_original_point_complex_mf_response

   !> One direction of dpcm_original_point_complex_mf_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_complex_mf_response_one(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_complex_state), target, intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:)
      !> Direction for vn
      complex(wp), contiguous, intent(in) :: dvn(:)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:)
      !> Hessian times direction, vn block
      complex(wp), contiguous, intent(out) :: hvp_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp), allocatable :: tmp1(:), tmp2(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_response_one] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_response_one] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt])) then
         call fatal_error(error, &
                          "[dpcm_original_point_complex_mf_response_one] hvp_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_response_one] allocation failed")
         return
      end if

      state%op4%points => state%r
      state%op4%r => state%r
      state%op4%n => state%n
      state%op4%k1 => state%k1
      state%op4%k2 => state%k2
      state%op4%a => state%a
      state%op4%c1 => state%s3
      tmp1 = 0.0_wp
      call state%solver%solve_complex(state%op4, .false., dvn, tmp1, error)
      if (allocated(error)) return
      hvp_v = state%cx_s13*tmp1
      tmp2 = 0.0_wp
      call state%solver%solve_complex(state%op4, .true., dv, tmp2, error)
      if (allocated(error)) return
      hvp_vn = state%cx_s13*tmp2
   end subroutine dpcm_original_point_complex_mf_response_one

   !> DPCM, original form (point charges): energy derivatives with respect to the solvent parameters
   !>
   !> - For the inputs of the last solve; independent of weights, which does not compute them
   !> - Needs dpcm_original_point_complex_solve on the same state first
   !> - Keeps the state as it is; may be repeated in any order
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[out] grad_eps  partial derivative of the energy with respect to eps
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_complex_mf_param_weights(state, grad_eps, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_complex_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to eps
      complex(wp), intent(out) :: grad_eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp6(:)
      real(wp) :: tmp7, tmp8, tmp9, tmp10, tmp11, tmp12
      complex(wp), allocatable :: tmp1(:), tmp4(:), tmp5(:), tmp13(:)
      complex(wp) :: tmp2, tmp3, tmp42, tmp43, tmp44, tmp45, tmp46
      integer :: i, j

      stat = 0
      npt = state%npt
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[dpcm_original_point_complex_mf_param_weights] call dpcm_original_point_complex_solve first")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp13(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_param_weights] allocation failed")
         return
      end if

      state%op4%points => state%r
      state%op4%r => state%r
      state%op4%n => state%n
      state%op4%k1 => state%k1
      state%op4%k2 => state%k2
      state%op4%a => state%a
      state%op4%c1 => state%s3
      tmp1 = 0.5_wp*state%cx_v
      tmp2 = sum(tmp1*state%cx_s12)
      tmp3 = (-0.5_wp)*state%cx_s2
      tmp4 = tmp3*state%cx_s14
      do i = 1, npt
         tmp7 = state%k1(i) + state%k2(i)
         tmp8 = 1.0_wp/state%a(i)
         tmp9 = 12.566370614359172_wp*tmp8
         tmp10 = sqrt(tmp9)
         tmp11 = tmp7*tmp10
         tmp12 = (-0.26735_wp)*tmp11
         tmp6(i) = tmp12
      end do
      tmp13 = tmp6*state%cx_s12
      tmp5 = tmp13
      block
         real(wp) :: tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, tmp22, tmp25, tmp29, tmp23, tmp24, &
                     tmp26, tmp27, tmp28, tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, &
                     tmp38, tmp39, tmp40
         complex(wp) :: tmp21, tmp14, tmp41

         !$omp parallel &
         !$omp& private(i, j) &
         !$omp& shared(npt, state, tmp5) &
         !$omp& default(private)
         !$omp do schedule(static)
         do j = 1, npt
            tmp15 = state%s5(j)
            tmp16 = state%s6(j)
            tmp17 = state%s7(j)
            tmp18 = state%s8(j)
            tmp19 = state%s9(j)
            tmp20 = state%s10(j)
            tmp21 = state%cx_s12(j)
            tmp22 = -tmp16
            tmp25 = -tmp17
            tmp29 = -tmp19
            tmp14 = 0.0_wp
            !$omp simd &
            !$omp& private(tmp23, tmp24, tmp26, tmp27, tmp28, tmp30, tmp31, tmp32) &
            !$omp& private(tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, tmp39, tmp40) &
            !$omp& private(tmp41) &
            !$omp& reduction(+: tmp14)
            do i = 1, j - 1
               tmp23 = state%s6(i) + tmp22
               tmp24 = tmp15*tmp23
               tmp26 = state%s7(i) + tmp25
               tmp27 = tmp26*tmp18
               tmp28 = tmp24 + tmp27
               tmp30 = state%s9(i) + tmp29
               tmp31 = tmp30*tmp20
               tmp32 = tmp28 + tmp31
               tmp33 = tmp23**(2)
               tmp34 = tmp26**(2)
               tmp35 = tmp33 + tmp34
               tmp36 = tmp30**(2)
               tmp37 = tmp35 + tmp36
               tmp38 = 1.0_wp/sqrt(tmp37)
               tmp39 = tmp38**(3)
               tmp40 = tmp32*tmp39
               tmp41 = tmp40*state%cx_s12(i)
               tmp14 = tmp14 + tmp41
            end do
            !$omp simd &
            !$omp& private(tmp23, tmp24, tmp26, tmp27, tmp28, tmp30, tmp31, tmp32) &
            !$omp& private(tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, tmp39, tmp40) &
            !$omp& private(tmp41) &
            !$omp& reduction(+: tmp14)
            do i = j + 1, npt
               tmp23 = state%s6(i) + tmp22
               tmp24 = tmp15*tmp23
               tmp26 = state%s7(i) + tmp25
               tmp27 = tmp26*tmp18
               tmp28 = tmp24 + tmp27
               tmp30 = state%s9(i) + tmp29
               tmp31 = tmp30*tmp20
               tmp32 = tmp28 + tmp31
               tmp33 = tmp23**(2)
               tmp34 = tmp26**(2)
               tmp35 = tmp33 + tmp34
               tmp36 = tmp30**(2)
               tmp37 = tmp35 + tmp36
               tmp38 = 1.0_wp/sqrt(tmp37)
               tmp39 = tmp38**(3)
               tmp40 = tmp32*tmp39
               tmp41 = tmp40*state%cx_s12(i)
               tmp14 = tmp14 + tmp41
            end do
            tmp5(j) = tmp5(j) + tmp14
         end do
         !$omp end do
         !$omp end parallel
      end block
      tmp42 = sum(tmp4*tmp5)
      tmp43 = -tmp42
      tmp44 = tmp2 + tmp43
      tmp45 = state%cx_s1**(-2)
      tmp46 = tmp44*tmp45
      grad_eps = 2.0_wp*tmp46
   end subroutine dpcm_original_point_complex_mf_param_weights

   !> Apply operator 1 or its transpose
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine dpcm_original_point_op1_apply(self, trans, x, y)
      !> Operator
      class(dpcm_original_point_op1), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         call dpcm_original_point_op1_apply_t(self, x, y)
      else
         call dpcm_original_point_op1_apply_n(self, x, y)
      end if
   end subroutine dpcm_original_point_op1_apply

   !> Apply the transpose of operator 1
   !>
   !> @param[in]  self  operator
   !> @param[in]  x     input vector
   !> @param[out] y     result vector
   subroutine dpcm_original_point_op1_apply_t(self, x, y)
      !> Operator
      class(dpcm_original_point_op1), intent(in) :: self
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:)

      allocate (tmp1(self%npt))
      allocate (tmp2(self%npt))
      allocate (tmp3(self%npt))
      allocate (tmp4(self%npt))
      tmp1 = self%c1*x
      tmp2 = 6.283185307179586_wp*tmp1
      call gemv(self%c3, x, tmp3)
      tmp4 = self%c2*tmp3
      y = tmp2 + tmp4
   end subroutine dpcm_original_point_op1_apply_t

   !> Apply operator 1
   !>
   !> @param[in]  self  operator
   !> @param[in]  x     input vector
   !> @param[out] y     result vector
   subroutine dpcm_original_point_op1_apply_n(self, x, y)
      !> Operator
      class(dpcm_original_point_op1), intent(in) :: self
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:)

      allocate (tmp1(self%npt))
      allocate (tmp2(self%npt))
      allocate (tmp3(self%npt))
      allocate (tmp4(self%npt))
      tmp1 = self%c1*x
      tmp2 = 6.283185307179586_wp*tmp1
      call gemv(self%c3, x, tmp3, trans="t")
      tmp4 = self%c2*tmp3
      y = tmp2 + tmp4
   end subroutine dpcm_original_point_op1_apply_n

   !> Form operator 1 as a dense matrix
   !>
   !> @param[in]  self  operator
   !> @param[out] a     matrix of shape (npt, npt)
   !> @param[out] error  error handling; allocated if workspace allocation failed
   subroutine dpcm_original_point_op1_assemble(self, a, error)
      !> Operator
      class(dpcm_original_point_op1), intent(in) :: self
      !> Dense operator matrix
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: stat
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :), tmp3(:, :), tmp4(:, :)
      integer :: i

      allocate (tmp1(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp2(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp3(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp4(self%npt, self%npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_op1_assemble] allocation failed")
         return
      end if
      tmp1 = 0.0_wp
      do i = 1, self%npt
         tmp1(i, i) = self%c1(i)
      end do
      tmp2 = 6.283185307179586_wp*tmp1
      tmp3 = transpose(self%c3)
      tmp4 = self%c2*tmp3
      a = tmp2 + tmp4
   end subroutine dpcm_original_point_op1_assemble

   !> Form operator 1 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine dpcm_original_point_op1_assemble_block(self, idx, a, error)
      !> Operator
      class(dpcm_original_point_op1), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp1(:)
      real(wp), allocatable :: tmp2(:, :), tmp3(:, :), tmp4(:, :), tmp5(:, :), tmp6(:, :)
      integer :: i

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[dpcm_original_point_op1_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(nb), stat=stat)
      if (stat == 0) allocate (tmp2(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp3(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp4(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp5(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp6(nb, nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_op1_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%c1(idx)
      tmp2 = self%c3(idx, idx)
      tmp3 = 0.0_wp
      do i = 1, nb
         tmp3(i, i) = tmp1(i)
      end do
      tmp4 = 6.283185307179586_wp*tmp3
      tmp5 = transpose(tmp2)
      tmp6 = self%c2*tmp5
      a = tmp4 + tmp6
   end subroutine dpcm_original_point_op1_assemble_block

   !> Apply operator 2 or its transpose
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine dpcm_original_point_op2_apply(self, trans, x, y)
      !> Operator
      class(dpcm_original_point_op2), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         call dpcm_original_point_op2_apply_t(self, x, y)
      else
         call dpcm_original_point_op2_apply_n(self, x, y)
      end if
   end subroutine dpcm_original_point_op2_apply

   !> Apply the transpose of operator 2
   !>
   !> @param[in]  self  operator
   !> @param[in]  x     input vector
   !> @param[out] y     result vector
   subroutine dpcm_original_point_op2_apply_t(self, x, y)
      !> Operator
      class(dpcm_original_point_op2), intent(in) :: self
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp11(:), tmp39(:)
      real(wp) :: tmp5, tmp6, tmp7, tmp8, tmp9, tmp10
      real(wp), allocatable :: tmp3_p(:)
      integer :: i, j

      allocate (tmp1(self%npt))
      allocate (tmp2(self%npt))
      allocate (tmp3(self%npt))
      allocate (tmp4(self%npt))
      allocate (tmp11(self%npt))
      allocate (tmp39(self%npt))
      tmp1 = self%c1*x
      tmp2 = 6.283185307179586_wp*tmp1
      do i = 1, self%npt
         tmp5 = self%k1(i) + self%k2(i)
         tmp6 = 1.0_wp/self%a(i)
         tmp7 = 12.566370614359172_wp*tmp6
         tmp8 = sqrt(tmp7)
         tmp9 = tmp5*tmp8
         tmp10 = (-0.26735_wp)*tmp9
         tmp4(i) = tmp10
      end do
      tmp11 = tmp4*x
      tmp3 = tmp11
      block
         real(wp) :: tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp22, tmp26, tmp20, &
                     tmp21, tmp23, tmp24, tmp25, tmp27, tmp28, tmp29, tmp30, tmp31, tmp32, tmp33, &
                     tmp34, tmp35, tmp36, tmp37, tmp38

         !$omp parallel &
         !$omp& private(i, j, tmp3_p) &
         !$omp& shared(self, tmp3, x) &
         !$omp& default(private)
         allocate (tmp3_p(self%npt))
         tmp3_p = 0.0_wp
         !$omp do schedule(static)
         do j = 1, self%npt
            tmp12 = self%n(1, j)
            tmp13 = self%r(1, j)
            tmp14 = self%r(2, j)
            tmp15 = self%n(2, j)
            tmp16 = self%r(3, j)
            tmp17 = self%n(3, j)
            tmp18 = x(j)
            tmp19 = -tmp13
            tmp22 = -tmp14
            tmp26 = -tmp16
            !$omp simd &
            !$omp& private(tmp20, tmp21, tmp23, tmp24, tmp25, tmp27, tmp28, tmp29) &
            !$omp& private(tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37) &
            !$omp& private(tmp38)
            do i = 1, j - 1
               tmp20 = self%r(1, i) + tmp19
               tmp21 = tmp12*tmp20
               tmp23 = self%r(2, i) + tmp22
               tmp24 = tmp23*tmp15
               tmp25 = tmp21 + tmp24
               tmp27 = self%r(3, i) + tmp26
               tmp28 = tmp27*tmp17
               tmp29 = tmp25 + tmp28
               tmp30 = tmp29*tmp18
               tmp31 = tmp20**(2)
               tmp32 = tmp23**(2)
               tmp33 = tmp31 + tmp32
               tmp34 = tmp27**(2)
               tmp35 = tmp33 + tmp34
               tmp36 = 1.0_wp/sqrt(tmp35)
               tmp37 = tmp36**(3)
               tmp38 = tmp30*tmp37
               tmp3_p(i) = tmp3_p(i) + tmp38
            end do
            !$omp simd &
            !$omp& private(tmp20, tmp21, tmp23, tmp24, tmp25, tmp27, tmp28, tmp29) &
            !$omp& private(tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37) &
            !$omp& private(tmp38)
            do i = j + 1, self%npt
               tmp20 = self%r(1, i) + tmp19
               tmp21 = tmp12*tmp20
               tmp23 = self%r(2, i) + tmp22
               tmp24 = tmp23*tmp15
               tmp25 = tmp21 + tmp24
               tmp27 = self%r(3, i) + tmp26
               tmp28 = tmp27*tmp17
               tmp29 = tmp25 + tmp28
               tmp30 = tmp29*tmp18
               tmp31 = tmp20**(2)
               tmp32 = tmp23**(2)
               tmp33 = tmp31 + tmp32
               tmp34 = tmp27**(2)
               tmp35 = tmp33 + tmp34
               tmp36 = 1.0_wp/sqrt(tmp35)
               tmp37 = tmp36**(3)
               tmp38 = tmp30*tmp37
               tmp3_p(i) = tmp3_p(i) + tmp38
            end do
         end do
         !$omp end do
         !$omp critical (pcmgen_sum)
         tmp3 = tmp3 + tmp3_p
         !$omp end critical (pcmgen_sum)
         deallocate (tmp3_p)
         !$omp end parallel
      end block
      tmp39 = self%c2*tmp3
      y = tmp2 + tmp39
   end subroutine dpcm_original_point_op2_apply_t

   !> Apply operator 2
   !>
   !> @param[in]  self  operator
   !> @param[in]  x     input vector
   !> @param[out] y     result vector
   subroutine dpcm_original_point_op2_apply_n(self, x, y)
      !> Operator
      class(dpcm_original_point_op2), intent(in) :: self
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp11(:), tmp40(:)
      real(wp) :: tmp5, tmp6, tmp7, tmp8, tmp9, tmp10
      integer :: i, j

      allocate (tmp1(self%npt))
      allocate (tmp2(self%npt))
      allocate (tmp3(self%npt))
      allocate (tmp4(self%npt))
      allocate (tmp11(self%npt))
      allocate (tmp40(self%npt))
      tmp1 = self%c1*x
      tmp2 = 6.283185307179586_wp*tmp1
      do i = 1, self%npt
         tmp5 = self%k1(i) + self%k2(i)
         tmp6 = 1.0_wp/self%a(i)
         tmp7 = 12.566370614359172_wp*tmp6
         tmp8 = sqrt(tmp7)
         tmp9 = tmp5*tmp8
         tmp10 = (-0.26735_wp)*tmp9
         tmp4(i) = tmp10
      end do
      tmp11 = tmp4*x
      tmp3 = tmp11
      block
         real(wp) :: tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, tmp23, tmp27, tmp12, &
                     tmp21, tmp22, tmp24, tmp25, tmp26, tmp28, tmp29, tmp30, tmp31, tmp32, tmp33, &
                     tmp34, tmp35, tmp36, tmp37, tmp38, tmp39

         !$omp parallel &
         !$omp& private(i, j) &
         !$omp& shared(self, tmp3, x) &
         !$omp& default(private)
         !$omp do schedule(static)
         do j = 1, self%npt
            tmp13 = x(j)
            tmp14 = self%n(1, j)
            tmp15 = self%r(1, j)
            tmp16 = self%r(2, j)
            tmp17 = self%n(2, j)
            tmp18 = self%r(3, j)
            tmp19 = self%n(3, j)
            tmp20 = -tmp15
            tmp23 = -tmp16
            tmp27 = -tmp18
            tmp12 = 0.0_wp
            !$omp simd &
            !$omp& private(tmp21, tmp22, tmp24, tmp25, tmp26, tmp28, tmp29, tmp30) &
            !$omp& private(tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38) &
            !$omp& private(tmp39) &
            !$omp& reduction(+: tmp12)
            do i = 1, j - 1
               tmp21 = self%r(1, i) + tmp20
               tmp22 = tmp14*tmp21
               tmp24 = self%r(2, i) + tmp23
               tmp25 = tmp24*tmp17
               tmp26 = tmp22 + tmp25
               tmp28 = self%r(3, i) + tmp27
               tmp29 = tmp28*tmp19
               tmp30 = tmp26 + tmp29
               tmp31 = x(i)*tmp30
               tmp32 = tmp21**(2)
               tmp33 = tmp24**(2)
               tmp34 = tmp32 + tmp33
               tmp35 = tmp28**(2)
               tmp36 = tmp34 + tmp35
               tmp37 = 1.0_wp/sqrt(tmp36)
               tmp38 = tmp37**(3)
               tmp39 = tmp31*tmp38
               tmp12 = tmp12 + tmp39
            end do
            !$omp simd &
            !$omp& private(tmp21, tmp22, tmp24, tmp25, tmp26, tmp28, tmp29, tmp30) &
            !$omp& private(tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38) &
            !$omp& private(tmp39) &
            !$omp& reduction(+: tmp12)
            do i = j + 1, self%npt
               tmp21 = self%r(1, i) + tmp20
               tmp22 = tmp14*tmp21
               tmp24 = self%r(2, i) + tmp23
               tmp25 = tmp24*tmp17
               tmp26 = tmp22 + tmp25
               tmp28 = self%r(3, i) + tmp27
               tmp29 = tmp28*tmp19
               tmp30 = tmp26 + tmp29
               tmp31 = x(i)*tmp30
               tmp32 = tmp21**(2)
               tmp33 = tmp24**(2)
               tmp34 = tmp32 + tmp33
               tmp35 = tmp28**(2)
               tmp36 = tmp34 + tmp35
               tmp37 = 1.0_wp/sqrt(tmp36)
               tmp38 = tmp37**(3)
               tmp39 = tmp31*tmp38
               tmp12 = tmp12 + tmp39
            end do
            tmp3(j) = tmp3(j) + tmp12
         end do
         !$omp end do
         !$omp end parallel
      end block
      tmp40 = self%c2*tmp3
      y = tmp2 + tmp40
   end subroutine dpcm_original_point_op2_apply_n

   !> Form operator 2 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine dpcm_original_point_op2_assemble_block(self, idx, a, error)
      !> Operator
      class(dpcm_original_point_op2), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp3(:), tmp4(:), tmp5(:), tmp6(:)
      real(wp), allocatable :: tmp7(:, :), tmp8(:, :), tmp9(:, :), tmp44(:, :), tmp45(:, :)
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :)
      real(wp) :: tmp38, tmp39, tmp40, tmp41, tmp42, tmp43
      integer :: i, j

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[dpcm_original_point_op2_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(3, nb), stat=stat)
      if (stat == 0) allocate (tmp2(3, nb), stat=stat)
      if (stat == 0) allocate (tmp3(nb), stat=stat)
      if (stat == 0) allocate (tmp4(nb), stat=stat)
      if (stat == 0) allocate (tmp5(nb), stat=stat)
      if (stat == 0) allocate (tmp6(nb), stat=stat)
      if (stat == 0) allocate (tmp7(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp8(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp9(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp44(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp45(nb, nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_op2_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%r(:, idx)
      tmp2 = self%n(:, idx)
      tmp3 = self%k1(idx)
      tmp4 = self%k2(idx)
      tmp5 = self%a(idx)
      tmp6 = self%c1(idx)
      tmp7 = 0.0_wp
      do i = 1, nb
         tmp7(i, i) = tmp6(i)
      end do
      tmp8 = 6.283185307179586_wp*tmp7
      block
         real(wp) :: tmp10, tmp11, tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, &
                     tmp21, tmp22, tmp23, tmp24, tmp25, tmp26, tmp27, tmp28, tmp29, tmp30, tmp31, &
                     tmp32, tmp33, tmp34, tmp35, tmp36, tmp37

         !$omp parallel do schedule(dynamic, 16) &
         !$omp& private(i) &
         !$omp& shared(nb, tmp1, tmp2, tmp9) &
         !$omp& default(private)
         do j = 1, nb
            do i = 1, j - 1
               tmp10 = -tmp1(1, j)
               tmp11 = tmp1(1, i) + tmp10
               tmp12 = tmp2(1, j)*tmp11
               tmp13 = -tmp1(2, j)
               tmp14 = tmp1(2, i) + tmp13
               tmp15 = tmp14*tmp2(2, j)
               tmp16 = tmp12 + tmp15
               tmp17 = -tmp1(3, j)
               tmp18 = tmp1(3, i) + tmp17
               tmp19 = tmp18*tmp2(3, j)
               tmp20 = tmp16 + tmp19
               tmp21 = tmp11**(2)
               tmp22 = tmp14**(2)
               tmp23 = tmp21 + tmp22
               tmp24 = tmp18**(2)
               tmp25 = tmp23 + tmp24
               tmp26 = 1.0_wp/sqrt(tmp25)
               tmp27 = tmp26**(3)
               tmp28 = tmp20*tmp27
               tmp9(i, j) = tmp28
               tmp29 = -tmp11
               tmp30 = tmp2(1, i)*tmp29
               tmp31 = -tmp14
               tmp32 = tmp31*tmp2(2, i)
               tmp33 = tmp30 + tmp32
               tmp34 = -tmp18
               tmp35 = tmp34*tmp2(3, i)
               tmp36 = tmp33 + tmp35
               tmp37 = tmp36*tmp27
               tmp9(j, i) = tmp37
            end do
         end do
         !$omp end parallel do
      end block
      do i = 1, nb
         tmp38 = tmp3(i) + tmp4(i)
         tmp39 = 1.0_wp/tmp5(i)
         tmp40 = 12.566370614359172_wp*tmp39
         tmp41 = sqrt(tmp40)
         tmp42 = tmp38*tmp41
         tmp43 = (-0.26735_wp)*tmp42
         tmp9(i, i) = tmp43
      end do
      tmp44 = transpose(tmp9)
      tmp45 = self%c2*tmp44
      a = tmp8 + tmp45
   end subroutine dpcm_original_point_op2_assemble_block

   !> Apply operator 3 or its transpose (not conjugated)
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine dpcm_original_point_op3_apply(self, trans, x, y)
      !> Operator
      class(dpcm_original_point_op3), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      complex(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      complex(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         call dpcm_original_point_op3_apply_t(self, x, y)
      else
         call dpcm_original_point_op3_apply_n(self, x, y)
      end if
   end subroutine dpcm_original_point_op3_apply

   !> Apply the transpose of operator 3 (not conjugated)
   !>
   !> @param[in]  self  operator
   !> @param[in]  x     input vector
   !> @param[out] y     result vector
   subroutine dpcm_original_point_op3_apply_t(self, x, y)
      !> Operator
      class(dpcm_original_point_op3), intent(in) :: self
      !> Input vector
      complex(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      complex(wp), contiguous, intent(out) :: y(:)

      real(wp), allocatable :: tmp4(:), tmp5(:)
      complex(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp6(:)

      allocate (tmp1(self%npt))
      allocate (tmp2(self%npt))
      allocate (tmp3(self%npt))
      allocate (tmp4(self%npt))
      allocate (tmp5(self%npt))
      allocate (tmp6(self%npt))
      tmp1 = self%c1*x
      tmp2 = 6.283185307179586_wp*tmp1
      call gemv(self%c3, real(x, wp), tmp4)
      call gemv(self%c3, aimag(x), tmp5)
      tmp3 = cmplx(tmp4, tmp5, wp)
      tmp6 = self%c2*tmp3
      y = tmp2 + tmp6
   end subroutine dpcm_original_point_op3_apply_t

   !> Apply operator 3
   !>
   !> @param[in]  self  operator
   !> @param[in]  x     input vector
   !> @param[out] y     result vector
   subroutine dpcm_original_point_op3_apply_n(self, x, y)
      !> Operator
      class(dpcm_original_point_op3), intent(in) :: self
      !> Input vector
      complex(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      complex(wp), contiguous, intent(out) :: y(:)

      real(wp), allocatable :: tmp4(:), tmp5(:)
      complex(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp6(:)

      allocate (tmp1(self%npt))
      allocate (tmp2(self%npt))
      allocate (tmp3(self%npt))
      allocate (tmp4(self%npt))
      allocate (tmp5(self%npt))
      allocate (tmp6(self%npt))
      tmp1 = self%c1*x
      tmp2 = 6.283185307179586_wp*tmp1
      call gemv(self%c3, real(x, wp), tmp4, trans="t")
      call gemv(self%c3, aimag(x), tmp5, trans="t")
      tmp3 = cmplx(tmp4, tmp5, wp)
      tmp6 = self%c2*tmp3
      y = tmp2 + tmp6
   end subroutine dpcm_original_point_op3_apply_n

   !> Form operator 3 as a dense matrix
   !>
   !> @param[in]  self  operator
   !> @param[out] a     matrix of shape (npt, npt)
   !> @param[out] error  error handling; allocated if workspace allocation failed
   subroutine dpcm_original_point_op3_assemble(self, a, error)
      !> Operator
      class(dpcm_original_point_op3), intent(in) :: self
      !> Dense operator matrix
      complex(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: stat
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :), tmp3(:, :)
      complex(wp), allocatable :: tmp4(:, :)
      integer :: i

      allocate (tmp1(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp2(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp3(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp4(self%npt, self%npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_op3_assemble] allocation failed")
         return
      end if
      tmp1 = 0.0_wp
      do i = 1, self%npt
         tmp1(i, i) = self%c1(i)
      end do
      tmp2 = 6.283185307179586_wp*tmp1
      tmp3 = transpose(self%c3)
      tmp4 = self%c2*tmp3
      a = tmp2 + tmp4
   end subroutine dpcm_original_point_op3_assemble

   !> Form operator 3 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine dpcm_original_point_op3_assemble_block(self, idx, a, error)
      !> Operator
      class(dpcm_original_point_op3), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      complex(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp1(:)
      real(wp), allocatable :: tmp2(:, :), tmp3(:, :), tmp4(:, :), tmp5(:, :)
      complex(wp), allocatable :: tmp6(:, :)
      integer :: i

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[dpcm_original_point_op3_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(nb), stat=stat)
      if (stat == 0) allocate (tmp2(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp3(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp4(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp5(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp6(nb, nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_op3_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%c1(idx)
      tmp2 = self%c3(idx, idx)
      tmp3 = 0.0_wp
      do i = 1, nb
         tmp3(i, i) = tmp1(i)
      end do
      tmp4 = 6.283185307179586_wp*tmp3
      tmp5 = transpose(tmp2)
      tmp6 = self%c2*tmp5
      a = tmp4 + tmp6
   end subroutine dpcm_original_point_op3_assemble_block

   !> Apply operator 4 or its transpose (not conjugated)
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine dpcm_original_point_op4_apply(self, trans, x, y)
      !> Operator
      class(dpcm_original_point_op4), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      complex(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      complex(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         call dpcm_original_point_op4_apply_t(self, x, y)
      else
         call dpcm_original_point_op4_apply_n(self, x, y)
      end if
   end subroutine dpcm_original_point_op4_apply

   !> Apply the transpose of operator 4 (not conjugated)
   !>
   !> @param[in]  self  operator
   !> @param[in]  x     input vector
   !> @param[out] y     result vector
   subroutine dpcm_original_point_op4_apply_t(self, x, y)
      !> Operator
      class(dpcm_original_point_op4), intent(in) :: self
      !> Input vector
      complex(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      complex(wp), contiguous, intent(out) :: y(:)

      real(wp), allocatable :: tmp4(:)
      real(wp) :: tmp5, tmp6, tmp7, tmp8, tmp9, tmp10
      complex(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp11(:), tmp39(:)
      complex(wp), allocatable :: tmp3_p(:)
      integer :: i, j

      allocate (tmp1(self%npt))
      allocate (tmp2(self%npt))
      allocate (tmp3(self%npt))
      allocate (tmp4(self%npt))
      allocate (tmp11(self%npt))
      allocate (tmp39(self%npt))
      tmp1 = self%c1*x
      tmp2 = 6.283185307179586_wp*tmp1
      do i = 1, self%npt
         tmp5 = self%k1(i) + self%k2(i)
         tmp6 = 1.0_wp/self%a(i)
         tmp7 = 12.566370614359172_wp*tmp6
         tmp8 = sqrt(tmp7)
         tmp9 = tmp5*tmp8
         tmp10 = (-0.26735_wp)*tmp9
         tmp4(i) = tmp10
      end do
      tmp11 = tmp4*x
      tmp3 = tmp11
      block
         real(wp) :: tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp19, tmp22, tmp26, tmp20, tmp21, &
                     tmp23, tmp24, tmp25, tmp27, tmp28, tmp29, tmp31, tmp32, tmp33, tmp34, tmp35, &
                     tmp36, tmp37
         complex(wp) :: tmp18, tmp30, tmp38

         !$omp parallel &
         !$omp& private(i, j, tmp3_p) &
         !$omp& shared(self, tmp3, x) &
         !$omp& default(private)
         allocate (tmp3_p(self%npt))
         tmp3_p = 0.0_wp
         !$omp do schedule(static)
         do j = 1, self%npt
            tmp12 = self%n(1, j)
            tmp13 = self%r(1, j)
            tmp14 = self%r(2, j)
            tmp15 = self%n(2, j)
            tmp16 = self%r(3, j)
            tmp17 = self%n(3, j)
            tmp18 = x(j)
            tmp19 = -tmp13
            tmp22 = -tmp14
            tmp26 = -tmp16
            !$omp simd &
            !$omp& private(tmp20, tmp21, tmp23, tmp24, tmp25, tmp27, tmp28, tmp29) &
            !$omp& private(tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37) &
            !$omp& private(tmp38)
            do i = 1, j - 1
               tmp20 = self%r(1, i) + tmp19
               tmp21 = tmp12*tmp20
               tmp23 = self%r(2, i) + tmp22
               tmp24 = tmp23*tmp15
               tmp25 = tmp21 + tmp24
               tmp27 = self%r(3, i) + tmp26
               tmp28 = tmp27*tmp17
               tmp29 = tmp25 + tmp28
               tmp30 = tmp29*tmp18
               tmp31 = tmp20**(2)
               tmp32 = tmp23**(2)
               tmp33 = tmp31 + tmp32
               tmp34 = tmp27**(2)
               tmp35 = tmp33 + tmp34
               tmp36 = 1.0_wp/sqrt(tmp35)
               tmp37 = tmp36**(3)
               tmp38 = tmp30*tmp37
               tmp3_p(i) = tmp3_p(i) + tmp38
            end do
            !$omp simd &
            !$omp& private(tmp20, tmp21, tmp23, tmp24, tmp25, tmp27, tmp28, tmp29) &
            !$omp& private(tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37) &
            !$omp& private(tmp38)
            do i = j + 1, self%npt
               tmp20 = self%r(1, i) + tmp19
               tmp21 = tmp12*tmp20
               tmp23 = self%r(2, i) + tmp22
               tmp24 = tmp23*tmp15
               tmp25 = tmp21 + tmp24
               tmp27 = self%r(3, i) + tmp26
               tmp28 = tmp27*tmp17
               tmp29 = tmp25 + tmp28
               tmp30 = tmp29*tmp18
               tmp31 = tmp20**(2)
               tmp32 = tmp23**(2)
               tmp33 = tmp31 + tmp32
               tmp34 = tmp27**(2)
               tmp35 = tmp33 + tmp34
               tmp36 = 1.0_wp/sqrt(tmp35)
               tmp37 = tmp36**(3)
               tmp38 = tmp30*tmp37
               tmp3_p(i) = tmp3_p(i) + tmp38
            end do
         end do
         !$omp end do
         !$omp critical (pcmgen_sum)
         tmp3 = tmp3 + tmp3_p
         !$omp end critical (pcmgen_sum)
         deallocate (tmp3_p)
         !$omp end parallel
      end block
      tmp39 = self%c2*tmp3
      y = tmp2 + tmp39
   end subroutine dpcm_original_point_op4_apply_t

   !> Apply operator 4
   !>
   !> @param[in]  self  operator
   !> @param[in]  x     input vector
   !> @param[out] y     result vector
   subroutine dpcm_original_point_op4_apply_n(self, x, y)
      !> Operator
      class(dpcm_original_point_op4), intent(in) :: self
      !> Input vector
      complex(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      complex(wp), contiguous, intent(out) :: y(:)

      real(wp), allocatable :: tmp4(:)
      real(wp) :: tmp5, tmp6, tmp7, tmp8, tmp9, tmp10
      complex(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp11(:), tmp40(:)
      integer :: i, j

      allocate (tmp1(self%npt))
      allocate (tmp2(self%npt))
      allocate (tmp3(self%npt))
      allocate (tmp4(self%npt))
      allocate (tmp11(self%npt))
      allocate (tmp40(self%npt))
      tmp1 = self%c1*x
      tmp2 = 6.283185307179586_wp*tmp1
      do i = 1, self%npt
         tmp5 = self%k1(i) + self%k2(i)
         tmp6 = 1.0_wp/self%a(i)
         tmp7 = 12.566370614359172_wp*tmp6
         tmp8 = sqrt(tmp7)
         tmp9 = tmp5*tmp8
         tmp10 = (-0.26735_wp)*tmp9
         tmp4(i) = tmp10
      end do
      tmp11 = tmp4*x
      tmp3 = tmp11
      block
         real(wp) :: tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, tmp23, tmp27, tmp21, tmp22, &
                     tmp24, tmp25, tmp26, tmp28, tmp29, tmp30, tmp32, tmp33, tmp34, tmp35, tmp36, &
                     tmp37, tmp38
         complex(wp) :: tmp13, tmp12, tmp31, tmp39

         !$omp parallel &
         !$omp& private(i, j) &
         !$omp& shared(self, tmp3, x) &
         !$omp& default(private)
         !$omp do schedule(static)
         do j = 1, self%npt
            tmp13 = x(j)
            tmp14 = self%n(1, j)
            tmp15 = self%r(1, j)
            tmp16 = self%r(2, j)
            tmp17 = self%n(2, j)
            tmp18 = self%r(3, j)
            tmp19 = self%n(3, j)
            tmp20 = -tmp15
            tmp23 = -tmp16
            tmp27 = -tmp18
            tmp12 = 0.0_wp
            !$omp simd &
            !$omp& private(tmp21, tmp22, tmp24, tmp25, tmp26, tmp28, tmp29, tmp30) &
            !$omp& private(tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38) &
            !$omp& private(tmp39) &
            !$omp& reduction(+: tmp12)
            do i = 1, j - 1
               tmp21 = self%r(1, i) + tmp20
               tmp22 = tmp14*tmp21
               tmp24 = self%r(2, i) + tmp23
               tmp25 = tmp24*tmp17
               tmp26 = tmp22 + tmp25
               tmp28 = self%r(3, i) + tmp27
               tmp29 = tmp28*tmp19
               tmp30 = tmp26 + tmp29
               tmp31 = x(i)*tmp30
               tmp32 = tmp21**(2)
               tmp33 = tmp24**(2)
               tmp34 = tmp32 + tmp33
               tmp35 = tmp28**(2)
               tmp36 = tmp34 + tmp35
               tmp37 = 1.0_wp/sqrt(tmp36)
               tmp38 = tmp37**(3)
               tmp39 = tmp31*tmp38
               tmp12 = tmp12 + tmp39
            end do
            !$omp simd &
            !$omp& private(tmp21, tmp22, tmp24, tmp25, tmp26, tmp28, tmp29, tmp30) &
            !$omp& private(tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38) &
            !$omp& private(tmp39) &
            !$omp& reduction(+: tmp12)
            do i = j + 1, self%npt
               tmp21 = self%r(1, i) + tmp20
               tmp22 = tmp14*tmp21
               tmp24 = self%r(2, i) + tmp23
               tmp25 = tmp24*tmp17
               tmp26 = tmp22 + tmp25
               tmp28 = self%r(3, i) + tmp27
               tmp29 = tmp28*tmp19
               tmp30 = tmp26 + tmp29
               tmp31 = x(i)*tmp30
               tmp32 = tmp21**(2)
               tmp33 = tmp24**(2)
               tmp34 = tmp32 + tmp33
               tmp35 = tmp28**(2)
               tmp36 = tmp34 + tmp35
               tmp37 = 1.0_wp/sqrt(tmp36)
               tmp38 = tmp37**(3)
               tmp39 = tmp31*tmp38
               tmp12 = tmp12 + tmp39
            end do
            tmp3(j) = tmp3(j) + tmp12
         end do
         !$omp end do
         !$omp end parallel
      end block
      tmp40 = self%c2*tmp3
      y = tmp2 + tmp40
   end subroutine dpcm_original_point_op4_apply_n

   !> Form operator 4 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine dpcm_original_point_op4_assemble_block(self, idx, a, error)
      !> Operator
      class(dpcm_original_point_op4), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      complex(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp3(:), tmp4(:), tmp5(:), tmp6(:)
      real(wp), allocatable :: tmp7(:, :), tmp8(:, :), tmp9(:, :), tmp44(:, :)
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :)
      real(wp) :: tmp38, tmp39, tmp40, tmp41, tmp42, tmp43
      complex(wp), allocatable :: tmp45(:, :)
      integer :: i, j

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[dpcm_original_point_op4_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(3, nb), stat=stat)
      if (stat == 0) allocate (tmp2(3, nb), stat=stat)
      if (stat == 0) allocate (tmp3(nb), stat=stat)
      if (stat == 0) allocate (tmp4(nb), stat=stat)
      if (stat == 0) allocate (tmp5(nb), stat=stat)
      if (stat == 0) allocate (tmp6(nb), stat=stat)
      if (stat == 0) allocate (tmp7(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp8(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp9(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp44(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp45(nb, nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_op4_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%r(:, idx)
      tmp2 = self%n(:, idx)
      tmp3 = self%k1(idx)
      tmp4 = self%k2(idx)
      tmp5 = self%a(idx)
      tmp6 = self%c1(idx)
      tmp7 = 0.0_wp
      do i = 1, nb
         tmp7(i, i) = tmp6(i)
      end do
      tmp8 = 6.283185307179586_wp*tmp7
      block
         real(wp) :: tmp10, tmp11, tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, &
                     tmp21, tmp22, tmp23, tmp24, tmp25, tmp26, tmp27, tmp28, tmp29, tmp30, tmp31, &
                     tmp32, tmp33, tmp34, tmp35, tmp36, tmp37

         !$omp parallel do schedule(dynamic, 16) &
         !$omp& private(i) &
         !$omp& shared(nb, tmp1, tmp2, tmp9) &
         !$omp& default(private)
         do j = 1, nb
            do i = 1, j - 1
               tmp10 = -tmp1(1, j)
               tmp11 = tmp1(1, i) + tmp10
               tmp12 = tmp2(1, j)*tmp11
               tmp13 = -tmp1(2, j)
               tmp14 = tmp1(2, i) + tmp13
               tmp15 = tmp14*tmp2(2, j)
               tmp16 = tmp12 + tmp15
               tmp17 = -tmp1(3, j)
               tmp18 = tmp1(3, i) + tmp17
               tmp19 = tmp18*tmp2(3, j)
               tmp20 = tmp16 + tmp19
               tmp21 = tmp11**(2)
               tmp22 = tmp14**(2)
               tmp23 = tmp21 + tmp22
               tmp24 = tmp18**(2)
               tmp25 = tmp23 + tmp24
               tmp26 = 1.0_wp/sqrt(tmp25)
               tmp27 = tmp26**(3)
               tmp28 = tmp20*tmp27
               tmp9(i, j) = tmp28
               tmp29 = -tmp11
               tmp30 = tmp2(1, i)*tmp29
               tmp31 = -tmp14
               tmp32 = tmp31*tmp2(2, i)
               tmp33 = tmp30 + tmp32
               tmp34 = -tmp18
               tmp35 = tmp34*tmp2(3, i)
               tmp36 = tmp33 + tmp35
               tmp37 = tmp36*tmp27
               tmp9(j, i) = tmp37
            end do
         end do
         !$omp end parallel do
      end block
      do i = 1, nb
         tmp38 = tmp3(i) + tmp4(i)
         tmp39 = 1.0_wp/tmp5(i)
         tmp40 = 12.566370614359172_wp*tmp39
         tmp41 = sqrt(tmp40)
         tmp42 = tmp38*tmp41
         tmp43 = (-0.26735_wp)*tmp42
         tmp9(i, i) = tmp43
      end do
      tmp44 = transpose(tmp9)
      tmp45 = self%c2*tmp44
      a = tmp8 + tmp45
   end subroutine dpcm_original_point_op4_assemble_block

end module pcmgen_point_dpcm_original
